insert into public.catalog_settings (id, terms, currency, price_note) values (true, E'•\nGoods Once Sold, Cannot Be Returned Back, strictly. \n•\nPayment Should Be Done in Advance. \n•\nAll Disputes Shall Be Subject to Rajkot Jurisdiction Only. \n•\nAny Manufacturing Defect Product Must Be Returned Within 15 Days. \n•\nGST Will Be Charged Extra as Applicable. \n•\nAll Prices Are Subject to Change Without Any Prior Notice. \n•\nGoods Travel at Buyer’s Risk. \n•\nCustomised Or Special-Order Items Are Non-Returnable. \n•\nAll Goods Subject to Rajkot Junction.', null, E'Prices are transcribed as printed. The supplied price lists do not state a currency. GST is extra. Prices can change without notice.') on conflict do nothing;
